styles.add(ParagraphStyle(name="Smallx", parent=styles["BodyText"], fontSize=8, leading=10))

def P(text, style="Bodyx"):
    return Paragraph(text, styles[style])

def bullets(items):
    return ListFlowable([ListItem(P(x), bulletColor=BLUE) for x in items], bulletType="bullet", leftIndent=18)

def tbl(headers, rows, widths):
    data = [[P(f"<b>{h}</b>", "Smallx") for h in headers]] + [[P(str(v), "Smallx") for v in row] for row in rows]
    t = Table(data, colWidths=[w*inch for w in widths], repeatRows=1, hAlign="LEFT")
    t.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), BLUE), ("TEXTCOLOR", (0,0), (-1,0), colors.white),
        ("GRID", (0,0), (-1,-1), 0.35, colors.HexColor("#D9D9D9")),
        ("VALIGN", (0,0), (-1,-1), "MIDDLE"), ("LEFTPADDING", (0,0), (-1,-1), 5),
        ("RIGHTPADDING", (0,0), (-1,-1), 5), ("TOPPADDING", (0,0), (-1,-1), 4),
        ("BOTTOMPADDING", (0,0), (-1,-1), 4),
    ] + [("BACKGROUND", (0,i), (-1,i), colors.HexColor("#F2F2F2")) for i in range(2, len(data), 2)]))
    return t

def footer(canvas, doc):
    canvas.saveState(); canvas.setFont("Helvetica", 8); canvas.setFillColor(colors.grey)
    canvas.drawCentredString(letter[0]/2, 0.45*inch, f"Taller 5 Núcleo 1 ITSQMET | Página {doc.page}")
    canvas.restoreState()

