story += [P("Tecnologías utilizadas", "H1x"), tbl(["Tecnología", "Uso"], [["Java 21", "Lenguaje de desarrollo"],["Spring Boot 4.1.1", "Configuración y ejecución"],["Spring MVC y Thymeleaf", "Interfaz web"],["Spring Data JPA e Hibernate", "Persistencia"],["MySQL", "Base de datos de entrega"],["H2", "Pruebas y perfil demo"],["Spring Security", "Autenticación y autorización"],["Maven Wrapper", "Construcción y pruebas"]], [2.2, 4.8]), P("Arquitectura MVC", "H1x"), P("La aplicación se organiza en capas. Los controladores reciben las solicitudes, los servicios concentran las reglas de negocio, los repositorios acceden a la base de datos y las entidades representan el modelo persistente. Las vistas Thymeleaf conforman la capa de presentación y los controladores REST exponen recursos JSON."), tbl(["Capa", "Implementación"], [["Model", "Usuario, Categoria, Producto, Pedido, Role y EstadoPedido"],["Repository", "Repositorios JpaRepository"],["Service", "Reglas de registro, CRUD, búsquedas y cálculos"],["Controller", "MVC web, autenticación y REST"],["View", "Plantillas login, registro, productos y pedidos"]], [1.5, 5.5]), P("Estructura del proyecto", "H1x"), P("La estructura relevante se encuentra dentro de src/main/java/com/example/tallernucleo1:"), bullets(["config/SecurityConfig.java", "model/", "repository/", "service/", "controller/", "src/main/resources/templates/", "src/test/java/", "src/test/resources/application-test.properties"])]
