story += [P("Spring Security", "H1x"), P("La configuración mantiene CSRF activo para la aplicación web y lo ignora únicamente para /api/**, donde las pruebas utilizan HTTP Basic. Las rutas GET públicas de productos y categorías no requieren autenticación. Las operaciones POST, PUT y DELETE administrativas requieren ROLE_ADMIN. Las contraseñas se codifican con BCrypt y el usuario ADMIN inicial se crea desde variables de entorno."), P("Pruebas realizadas y resultados", "H1x"), tbl(["Funcionalidad", "Procedimiento", "Esperado", "Obtenido", "Estado"], [["Compilación", ".\\mvnw.cmd test", "Sin errores", "Exitosa", "OK"],["Contexto Spring", "Prueba de contexto", "Cargar contexto", "H2 cargado", "OK"],["GET productos", "GET /api/productos", "200 público", "200", "OK"],["POST sin credenciales", "POST /api/productos", "401", "401", "OK"],["POST ADMIN", "POST /api/categorias Basic", "201", "201", "OK"],["POST USER", "POST /api/categorias Basic", "403", "403", "OK"],["Inicio demo", "spring-boot:run demo", "Iniciar", "Tomcat 8080", "OK"],["MySQL", "Configuración predeterminada", "Conectar", "Pendiente de credenciales", "PENDIENTE"]], [1.4, 2.6, 1.0, 1.1, 0.8]), P("Las pruebas automatizadas corresponden a ApiSecurityTests y TallerNucleo1ApplicationTests. Las pruebas de API adicionales se ejecutaron contra la instancia demo local mediante solicitudes HTTP."), P("Evidencias visuales", "H1x"), P("Se verificaron visualmente, mediante navegador, las siguientes pantallas: inicio de sesión con confirmación de registro, página principal de productos vacía y página de productos con el producto de prueba, stock 10 y valor de inventario 459.00."), bullets(["[CAPTURA PENDIENTE: estructura del proyecto en IDE]", "[CAPTURA PENDIENTE: tablas y relaciones en MySQL]", "[CAPTURA PENDIENTE: ejecución de pruebas Maven]", "[CAPTURA PENDIENTE: respuesta REST en Postman con 200, 201, 401, 403 y 404]"]), P("No se incluyen imágenes simuladas. Las capturas pendientes deben obtenerse en el equipo de entrega con MySQL activo y Postman/IDE abiertos."), P("Conclusiones", "H1x"), P("La implementación cubre la arquitectura MVC, persistencia JPA, CRUD de productos y categorías, gestión de pedidos, autenticación, autorización por roles, BCrypt, API REST y pruebas automatizadas. La instancia demo funciona y permite demostrar los flujos principales sin depender de una instalación externa."), P("La validación final contra MySQL y la incorporación de la carátula institucional permanecen pendientes porque no se dispuso de las credenciales de base de datos ni del archivo CARATULA.docx referenciado."), P("Recomendaciones", "H1x"), bullets(["Configurar DB_USERNAME y DB_PASSWORD sin escribirlos en archivos versionados.", "Tomar las capturas pendientes con la aplicación conectada a MySQL.", "Reemplazar los marcadores de carátula antes de entregar el informe.", "Cambiar ADMIN_PASSWORD para la demostración final."]), P("Referencias documentales", "H1x"), P("Guía de la Unidad de Integración Curricular Integración de la Información, Taller 5 Caso Práctico."), P("Transcripciones N1_Clase_01_05Oct, N1_Clase_02_06Oct, N1_Clase_03_07Oct y N1_Clase_04_09Oct.")]

